def transform(grid):
    points=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    r0=min(r for r,c in points); r1=max(r for r,c in points)
    c0=min(c for r,c in points); c1=max(c for r,c in points)
    obj=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    copies=sum(v==4 for row in grid for v in row)
    h,w=len(obj),len(obj[0])
    out=[[0]*(w*copies) for _ in range(h)]
    for k in range(copies):
        for r in range(h):
            for c in range(w):
                out[r][k*w+c]=obj[r][c]
    return out
